from fastapi import FastAPI, Depends, Response
from fastapi.testclient import TestClient
from typing import Annotated
import pytest

app = FastAPI()

def modify_response(response: Response):
    response.headers["X-Custom-Header"] = "CustomValue"
    return response

@app.get("/test-response-dep")
def endpoint(response: Annotated[Response, Depends(modify_response)]):
    return {"message": "Hello World"}

@app.get("/test-response-dep-alt")
def endpoint_alt(response: Response = Depends(modify_response)):
    return {"message": "Hello World"}

client = TestClient(app)

def test_response_dependency_annotated():
    response = client.get("/test-response-dep")
    assert response.status_code == 200
    assert response.json() == {"message": "Hello World"}
    assert response.headers["X-Custom-Header"] == "CustomValue"

def test_response_dependency_alt():
    response = client.get("/test-response-dep-alt")
    assert response.status_code == 200
    assert response.json() == {"message": "Hello World"}
    assert response.headers["X-Custom-Header"] == "CustomValue"

def test_regular_response_injection():
    @app.get("/test-regular-response")
    def regular_response(response: Response):
        response.headers["X-Regular"] = "Regular"
        return {"message": "Regular"}

    response = client.get("/test-regular-response")
    assert response.status_code == 200
    assert response.headers["X-Regular"] == "Regular"
